package org.apache.commons.math3.analysis.differentiation;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.atomic.AtomicReference;
import org.apache.commons.math3.exception.DimensionMismatchException;
import org.apache.commons.math3.exception.NumberIsTooLargeException;
import org.apache.commons.math3.util.ArithmeticUtils;
import org.apache.commons.math3.util.FastMath;
import org.apache.commons.math3.util.MathArrays;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for DSCompiler.atan2 method.
 * Maximizes branch and line coverage.
 */
public class DSCompiler_atan2_TriageGen2Test {

    private static final double EPSILON = 1e-14;

    @Test
    public void testAtan2_PositiveX() {
        // Test case where x >= 0
        int parameters = 1;
        int order = 1;
        DSCompiler compiler = DSCompiler.getCompiler(parameters, order);
        int size = compiler.getSize();

        double[] y = new double[size];
        double[] x = new double[size];
        double[] result = new double[size];

        // Set values: y = 1.0, x = 1.0 -> atan2(1, 1) = PI/4
        for (int i = 0; i < size; i++) {
            y[i] = 1.0;
            x[i] = 1.0;
        }

        compiler.atan2(y, 0, x, 0, result, 0);

        for (int i = 0; i < size; i++) {
            Assert.assertEquals("Atan2 failed for positive x at index " + i, 
                FastMath.atan2(1.0, 1.0), result[i], EPSILON);
        }
    }

    @Test
    public void testAtan2_NegativeX() {
        // Test case where x < 0
        int parameters = 1;
        int order = 1;
        DSCompiler compiler = DSCompiler.getCompiler(parameters, order);
        int size = compiler.getSize();

        double[] y = new double[size];
        double[] x = new double[size];
        double[] result = new double[size];

        // Set values: y = 1.0, x = -1.0 -> atan2(1, -1) = 3PI/4
        for (int i = 0; i < size; i++) {
            y[i] = 1.0;
            x[i] = -1.0;
        }

        compiler.atan2(y, 0, x, 0, result, 0);

        for (int i = 0; i < size; i++) {
            Assert.assertEquals("Atan2 failed for negative x at index " + i, 
                FastMath.atan2(1.0, -1.0), result[i], EPSILON);
        }
    }

    @Test
    public void testAtan2_SpecialCases() {
        int parameters = 1;
        int order = 0; // size 1
        DSCompiler compiler = DSCompiler.getCompiler(parameters, order);
        int size = compiler.getSize();

        double[] y = new double[size];
        double[] x = new double[size];
        double[] result = new double[size];

        // 1. Test (0, 0)
        y[0] = 0.0; x[0] = 0.0;
        compiler.atan2(y, 0, x, 0, result, 0);
        Assert.assertEquals(FastMath.atan2(0.0, 0.0), result[0], EPSILON);

        // 2. Test (+inf, +inf)
        y[0] = Double.POSITIVE_INFINITY; x[0] = Double.POSITIVE_INFINITY;
        compiler.atan2(y, 0, x, 0, result, 0);
        Assert.assertEquals(FastMath.atan2(Double.POSITIVE_INFINITY, Double.POSITIVE_INFINITY), result[0], EPSILON);

        // 3. Test (-inf, -inf)
        y[0] = Double.NEGATIVE_INFINITY; x[0] = Double.NEGATIVE_INFINITY;
        compiler.atan2(y, 0, x, 0, result, 0);
        Assert.assertEquals(FastMath.atan2(Double.NEGATIVE_INFINITY, Double.NEGATIVE_INFINITY), result[0], EPSILON);

        // 4. Test (0, -inf)
        y[0] = 0.0; x[0] = Double.NEGATIVE_INFINITY;
        compiler.atan2(y, 0, x, 0, result, 0);
        Assert.assertEquals(FastMath.atan2(0.0, Double.NEGATIVE_INFINITY), result[0], EPSILON);
    }

    @Test
    public void testAtan2_Offsets() {
        // Test that offsets are respected
        int parameters = 1;
        int order = 1;
        DSCompiler compiler = DSCompiler.getCompiler(parameters, order);
        int size = compiler.getSize();

        double[] y = new double[size + 1];
        double[] x = new double[size + 1];
        double[] result = new double[size + 1];

        // Fill with zeros
        for(int i=0; i<size+1; i++) { y[i]=0; x[i]=0; result[i]=99.0; }

        // Target index 1
        y[1] = 1.0;
        x[1] = 1.0;

        compiler.atan2(y, 1, x, 1, result, 1);

        Assert.assertEquals(FastMath.atan2(1.0, 1.0), result[1], EPSILON);
        Assert.assertEquals(99.0, result[0], EPSILON); // Ensure index 0 was not touched
    }

    @Test
    public void testAtan2_NegativeX_BranchLogic() {
        // Specifically target the 'else' block logic for result[resultOffset] vs result[resultOffset % i]
        // Note: The original code contains a potential bug/unusual logic: result[resultOffset % i] = -2 * tmp2[i]
        // We test to ensure the code executes without exception.
        int parameters = 2; 
        int order = 1; 
        DSCompiler compiler = DSCompiler.getCompiler(parameters, order);
        int size = compiler.getSize();

        double[] y = new double[size];
        double[] x = new double[size];
        double[] result = new double[size];

        for (int i = 0; i < size; i++) {
            y[i] = 1.0;
            x[i] = -1.0;
        }

        compiler.atan2(y, 0, x, 0, result, 0);

        // The final line of the method overwrites result[resultOffset] with FastMath.atan2
        // So we primarily verify the first element is correct.
        Assert.assertEquals(FastMath.atan2(1.0, -1.0), result[0], EPSILON);
    }
}
